'use strict';
// Independent, local-only design study. No source video, API calls, or real exports.
const concepts = {
  A: { name: '單一整合工作台', short: '一條主軸，集中操作', title: 'A / 一個時間座標，一個操作中心。', description: '移除重複的下方對照區，把原片、AI 候選、剪輯範圍與證據對齊在同一個寬工作台。影片下方只保留播放控制，剪輯不必在兩區來回找。', benefit: '最直接解決目前的重複', cost: '全片與局部共用一個視窗，找遠處片段時需要切換縮放。', axis: '單一主時間軸；對照、選取、證據共用刻度', audience: '希望保留熟悉操作，立即改善擁擠', recommendation: '優先推薦', task: '點「全片」看所有候選，再點「目前剪輯」放大。' },
  B: { name: '全片導覽＋局部精剪', short: '上看位置，下修細節', title: 'B / 兩種尺度，兩個清楚的任務。', description: '細長全片導覽只負責找位置，框線顯示目前放大的範圍；下方大時間軸專心調整這場戰鬥。兩條不共用縮放，卻始終知道彼此在哪裡。', benefit: '長 VOD 的方向感最好', cost: '仍有兩條時間軸，需要看清楚「全片」與「局部」標示。', axis: '全片導航＋獨立局部剪輯，放大範圍連動', audience: '常從長實況來回尋找多場挑戰', recommendation: '長 VOD 首選', task: '點全片候選，觀察下方精剪範圍與框線一起移動。' },
  C: { name: '分步專注工作區', short: '先找、再剪、最後核對', title: 'C / 一次只做一件事。', description: '把「找候選 → 精剪 → 核對」分成三個畫面。每一步都保留影片，時間軸只顯示當下需要的內容，讓操作空間留給目前的任務。', benefit: '第一次使用最容易理解', cost: '頻繁回頭比較候選時，會多一次切換步驟。', axis: '尋找時顯示全片；精剪時切換局部時間軸', audience: '偶爾剪一場，偏好清楚流程', recommendation: '適合新手', task: '試點三個步驟；修改範圍後回到核對，資料會保留。' },
  D: { name: '候選卡片＋精剪', short: '左選片段，右邊細修', title: 'D / 把候選當成片段，而不是一堆色塊。', description: '用左側卡片呈現每次挑戰的結果、摘要與時間，選取後在右側大播放器核對。只保留一條局部剪輯軸，減少理解多軌對照的負擔。', benefit: '候選意義最清楚，切換最快', cost: '較難一眼看出候選在整支影片中的距離與重疊。', axis: '候選以卡片取代時間軌，只留局部精剪', audience: 'AI 已找到候選，主要做篩選與微調', recommendation: '候選審閱首選', task: '切換左側候選；查看失敗片段不會覆寫勝利草稿。' },
  E: { name: '劇院＋剪輯抽屜', short: '看時放大，剪時展開', title: 'E / 空間跟著你的注意力移動。', description: '平常以大影片核對動作，要調整時展開下方剪輯抽屜，把對照、候選和精剪一次呈現。收合後保留片段摘要與預覽按鈕，不另外新增小時間軸。', benefit: '影片細節與操作空間可自由取捨', cost: '收合時無法直接調整，頻繁操作會多一次展開。', axis: '只有一套剪輯工作台，可展開、收合及調高', audience: '常仔細看動作，只偶爾微調邊界', recommendation: '觀看優先', task: '試收合抽屜放大影片，再展開；播放位置會保留。' }
};
const candidates = [
  { id: 1, start: 1112, end: 1235, kind: 'failure', tag: '失敗嘗試', title: '第一次接近勝利', detail: '死亡前仍有王的血條；排除。' },
  { id: 2, start: 1930, end: 2078, kind: 'fight', tag: '戰鬥片段', title: '第二階段戰鬥', detail: '尚未出現勝利訊號，待核對。' },
  { id: 3, start: 2536, end: 2710, kind: 'win', tag: '疑似勝利', title: '女武神 · 成功挑戰', detail: 'AI 偵測到勝利文字，收尾 8 秒。' }
];
const paths = { play:'<path d="m8 5 11 7-11 7Z"/>', pause:'<path d="M8 5v14M16 5v14"/>', back:'<path d="m14 6-6 6 6 6M4 5v14"/>', next:'<path d="m10 6 6 6-6 6M20 5v14"/>', scissors:'<circle cx="6" cy="6" r="3"/><circle cx="6" cy="18" r="3"/><path d="m8 8 12 12M8 16 20 4"/>', film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4M3 16h4M17 8h4M17 16h4"/>', spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>', target:'<circle cx="12" cy="12" r="7"/><circle cx="12" cy="12" r="2"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3"/>', check:'<path d="m5 12 4 4L19 6"/>', plus:'<path d="M12 5v14M5 12h14"/>', minus:'<path d="M5 12h14"/>', trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 13v6M8 21h8M10 19h4"/>', down:'<path d="m6 9 6 6 6-6"/>', up:'<path d="m6 15 6-6 6 6"/>', expand:'<path d="M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5"/>', export:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>', list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>' };
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.film}</svg>`;
const time = seconds => { const n = Math.max(0, Math.round(seconds)); return `${String(Math.floor(n / 3600)).padStart(2,'0')}:${String(Math.floor(n / 60) % 60).padStart(2,'0')}:${String(n % 60).padStart(2,'0')}`; };
const shortTime = seconds => time(seconds).slice(3);
const clamp = (x, min, max) => Math.max(min, Math.min(max, x));
const defaults = () => ({ selected:3, start:2536, victory:2702, postroll:8, current:2683, from:2520, to:2730, step:2, drawer:true, drawerHeight:310, playing:false, speed:1, reviewed:false, exported:false, showEvidence:false, error:'' });
const states = Object.fromEntries(Object.keys(concepts).map(key => [key, defaults()]));
let active = /^[A-E]$/.test(location.hash.slice(1)) ? location.hash.slice(1) : 'A';
let state = states[active];
let playUntil = null;
let drag = null;
const workspace = document.querySelector('#workspace');
const announce = text => { document.querySelector('#announcement').textContent = text; };
const button = (action, label, glyph, className = '', extras = '') => `<button type="button" data-action="${action}" class="${className}" ${extras}>${glyph ? icon(glyph) : ''}${label}</button>`;
function position(at, from=state.from, to=state.to) { return clamp((at-from)/(to-from)*100,0,100); }
function rangeStyle(start, end, from=state.from, to=state.to) { return `left:${position(start,from,to)}%;width:${Math.max(0,position(end,from,to)-position(start,from,to))}%`; }
function within(at,from,to){ return at>=from && at<=to; }
function localize(start=state.start,end=state.victory+state.postroll) { state.from=Math.max(0,start-16); state.to=Math.min(3600,end+20); }
function ruler(from,to) { return `<div class="ruler" aria-hidden="true">${Array.from({length:5},(_,i)=>`<span>${(to>=3600?time:shortTime)(from+(to-from)*i/4)}</span>`).join('')}</div>`; }
function playhead(from,to) { return `<span class="playhead" data-playhead data-from="${from}" data-to="${to}" style="left:${position(state.current,from,to)}%;display:${within(state.current,from,to)?'block':'none'}"></span>`; }
function seekInput(from,to,label) { return `<input class="seek-input" type="range" min="${from}" max="${to}" step="1" value="${clamp(state.current,from,to)}" data-seek aria-label="${label}" aria-valuetext="${time(state.current)}">`; }
function library() { return `<aside class="library" aria-label="素材庫示意"><div class="studio-brand"><span class="brand-symbol">${icon('scissors')}</span><span>BossCut</span></div><div class="library-import static">${icon('plus')} 匯入影片</div><p class="library-label">素材庫 / 02</p><div class="library-project">${icon('film')}<strong>艾爾登法環<br>女武神挑戰</strong><small>01:00:00 · 核對中</small></div><div class="library-other">黑暗靈魂 III</div><div class="library-footer"><span class="status-dot"></span> 本機剪輯工作區<br>DESIGN PROTOTYPE / ${active}</div></aside>`; }
function sceneArt(){ return `<svg class="scene-art" viewBox="0 0 1000 510" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#172722"/><stop offset="1" stop-color="#7b7952"/></linearGradient><linearGradient id="floor" x2="0" y2="1"><stop stop-color="#69704a"/><stop offset="1" stop-color="#20332a"/></linearGradient><radialGradient id="glow"><stop stop-color="#d5c487" stop-opacity=".55"/><stop offset="1" stop-color="#9eac6b" stop-opacity="0"/></radialGradient></defs><path fill="url(#sky)" d="M0 0h1000v510H0z"/><ellipse fill="url(#glow)" cx="655" cy="190" rx="400" ry="240"/><g fill="none" stroke="#111f1c" stroke-width="25" opacity=".75"><path d="M70 380Q190 200 120-80M125 110 40 20M120 170 260 30M850 380Q730 180 850-60M800 130 680 40M820 100 970 20"/><path stroke-width="9" d="M50 290Q310 170 390 20M950 320Q640 240 605-20M240 160 220-20M695 95 540 25"/></g><path d="M0 350Q300 320 500 353T1000 337V510H0Z" fill="url(#floor)"/><g stroke="#b8b088" opacity=".24" fill="none"><path d="m0 420 380-51 620 30M0 455l690-64 310 29M150 510l340-137M850 510 650 370M400 510l135-141"/></g><g fill="#d6cc97" opacity=".65">${Array.from({length:46},(_,i)=>`<ellipse cx="${(i*137+48)%1000}" cy="${355+(i*47)%148}" rx="${2+i%4}" ry="${1+i%2}"/>`).join('')}</g><g fill="#172821"><path d="M431 310q-13-43 5-48 23-5 25 20l-2 26 24 111-55 3-13-14Z"/><path d="m432 415-10 61 15 0 14-55 17 52h15l-9-64Z"/><path d="m455 315 27 40 49 8-3 8-58-5-33-33Z"/></g><path d="m508 364 104-115-94 128Z" fill="#c2b88e"/><g fill="#c4b386" opacity=".78"><path d="m666 247 12-24 15 9-4 25 25 67-54 0Z"/><path d="m669 319-14 40 11 1 20-31 13 32h11l-9-45Z"/></g><path d="M670 259q-64-28-84-91 75 16 96 79 53-57 127-47-43 63-119 72Z" fill="#9c7154" opacity=".5"/><g fill="#ede1b0" opacity=".65">${Array.from({length:16},(_,i)=>`<circle cx="${560+(i*53)%270}" cy="${100+(i*37)%240}" r="${1+i%2}"/>`).join('')}</g><rect width="1000" height="510" fill="#09140c" opacity=".13"/></svg>`; }
function player(){ return `<section class="player" aria-label="影片預覽示意"><div class="scene">${sceneArt()}<span class="scene-label">原片預覽 <span>／ 示意畫面</span></span><span class="scene-stamp mono">ELDEN RING / 1080p</span><div class="scene-event" data-scene-event></div><div class="scene-bottom">米凱拉的鋒刃 · 瑪蓮妮亞<div class="health-bar"><span data-health></span></div></div></div><div class="transport">${button('frame-back','','back','icon-button','aria-label="往前一秒"')}${button('play','','play','icon-button','aria-label="播放示意預覽" data-play-button')}${button('frame-next','','next','icon-button','aria-label="往後一秒"')}<div class="time-display mono"><strong data-current>${time(state.current)}</strong> <span>/ 01:00:00</span></div><label>速度 <select data-speed aria-label="示意播放速度"><option value="1" ${state.speed===1?'selected':''}>1×</option><option value="2" ${state.speed===2?'selected':''}>2×</option><option value="4" ${state.speed===4?'selected':''}>4×</option></select></label></div></section>`; }
function assistant(){ return `<aside class="assistant" aria-label="AI 建議示意"><div class="assistant-heading">${icon('spark')} 你的 AI 夥伴</div><p class="eyebrow">REVIEW THIS MOMENT</p><div class="ai-bubble">找到 <strong>3 段候選</strong>。<br><br><strong>#03</strong> 偵測到勝利文字，建議從 <strong class="mono">42:16</strong> 開始核對。<br><br>請確認開頭是完整的成功挑戰，並保留勝利後 <strong>8 秒</strong>。</div><div class="ai-signal"><span class="status-dot"></span> 示意結果 · 等待人工核對</div>${button('jump-victory','查看勝利位置','trophy')}</aside>`; }
function previewRow(){ return `<div class="preview-row">${player()}${assistant()}</div>`; }
function candidateBlocks(from,to) { return candidates.filter(c=>c.end>from&&c.start<to).map(c=>`<button type="button" class="candidate-block ${c.kind}" data-candidate="${c.id}" aria-label="查看候選 ${c.id}：${c.tag}，${time(c.start)} 至 ${time(c.end)}" aria-pressed="${state.selected===c.id}" style="${rangeStyle(c.start,c.end,from,to)}" title="#0${c.id} · ${c.tag} · ${time(c.start)}–${time(c.end)}">#0${c.id}${to-from<700?' '+c.tag:''}</button>`).join(''); }
function filmTrack(from,to) { return `<div class="track film-track" data-track data-from="${from}" data-to="${to}"><div class="filmstrip" aria-hidden="true">${Array.from({length:10},()=>'<div class="film-frame"></div>').join('')}</div>${seekInput(from,to,'局部原片播放位置')}<span class="selection" data-selection data-from="${from}" data-to="${to}" style="${rangeStyle(state.start,state.victory+state.postroll,from,to)}"></span><span class="selection-tail" data-tail data-from="${from}" data-to="${to}" style="${rangeStyle(state.victory,state.victory+state.postroll,from,to)}"></span>${['start','victory'].map(edge=>`<button type="button" class="boundary ${edge==='victory'?'victory-handle':''}" role="slider" aria-label="${edge==='start'?'剪輯開始位置':'勝利位置'}" aria-valuemin="${edge==='start'?0:state.start+1}" aria-valuemax="${edge==='start'?state.victory-1:3600-state.postroll}" aria-valuenow="${state[edge]}" aria-valuetext="${time(state[edge])}" data-edge="${edge}" data-from="${from}" data-to="${to}" style="left:${position(state[edge],from,to)}%;display:${within(state[edge],from,to)?'block':'none'}"></button>`).join('')}${playhead(from,to)}</div>`; }
function editControls(){ return `<div class="edit-controls"><label class="time-field">開始 <input data-time="start" aria-label="剪輯開始時間" value="${time(state.start)}" inputmode="numeric" pattern="[0-9]{2}:[0-9]{2}:[0-9]{2}" aria-describedby="edit-error"></label><div class="time-field">${button('start-minus','','minus','', 'aria-label="開始提早一秒"')}${button('start-plus','','plus','','aria-label="開始延後一秒"')}</div><label class="time-field">勝利 <input data-time="victory" aria-label="勝利時間" value="${time(state.victory)}" inputmode="numeric" pattern="[0-9]{2}:[0-9]{2}:[0-9]{2}" aria-describedby="edit-error"></label><label class="time-field">收尾 <select data-postroll aria-label="勝利後保留秒數">${[5,6,7,8,9,10].map(n=>`<option value="${n}" ${state.postroll===n?'selected':''}>${n} 秒</option>`).join('')}</select></label><span class="muted">結束 <span data-end class="mono">${time(state.victory+state.postroll)}</span></span></div><p id="edit-error" class="edit-error" role="status" ${state.error?'':'hidden'}>${state.error}</p>`; }
function timelinePanel({all=false,title='局部精剪',context=false}={}) { const {from,to}=state;return `<section class="timeline-panel" aria-label="${title}"><div class="timeline-heading"><h3>${icon('scissors')}${title}<small class="scale-label">${shortTime(from)}—${shortTime(to)} / ${Math.round(to-from)} 秒</small></h3><div class="timeline-tools">${button('fit','目前剪輯','target','',`aria-pressed="${to-from<700}"`)}${!['B','D'].includes(active)?button('full','全片', 'expand','',`aria-pressed="${to-from===3600}"`):button('zoom-in','放大','plus')}${button('evidence',state.showEvidence?'收起證據':'證據','list','',`aria-expanded="${state.showEvidence}"`)}</div></div>${context?`<p class="link-caption">${icon('target')} 對應上方框選範圍 · 獨立放大，保留全片方向感</p>`:''}<div class="timeline-grid"><span class="lane-label muted">原片時間</span>${ruler(from,to)}<span class="lane-label">${icon('film')}目前剪輯</span>${filmTrack(from,to)}${all?`<span class="lane-label">${icon('spark')}AI 候選</span><div class="track">${seekInput(from,to,'候選軌道播放位置')}${candidateBlocks(from,to)}${candidates.some(c=>c.start<to&&c.end>from)?'':'<span class="track-empty">此範圍沒有 AI 候選</span>'}<span class="track-selection" data-selection data-from="${from}" data-to="${to}" style="${rangeStyle(state.start,state.victory+state.postroll,from,to)}"></span>${playhead(from,to)}</div>`:''}${state.showEvidence?`<span class="lane-label">${icon('trophy')}勝利證據</span><div class="track">${seekInput(from,to,'證據軌道播放位置')}${within(2702,from,to)?`<button type="button" class="evidence-marker" data-action="evidence-victory" style="left:${position(2702,from,to)}%" aria-label="查看 AI 勝利證據 00:45:02">◆ 勝利文字</button>`:'<span class="track-empty">證據位於 45:02；可按「查看勝利位置」定位</span>'}${playhead(from,to)}</div>`:''}</div><div class="timeline-legend"><span><i class="legend-box outline"></i>框線：目前剪輯</span><span><i class="legend-box hatched"></i>斜線：勝利後收尾</span>${all?'<span><i class="legend-box"></i>色塊：AI 原始候選</span>':''}</div>${editControls()}${state.selected!==3?`<p class="context-note">${icon('list')} 正在查看 #0${state.selected}；勝利草稿仍保留在 42:16 附近。</p>`:''}</section>`; }
function overview(){ return `<section class="overview-panel" aria-label="全片導覽"><div class="overview-heading"><strong>全片導覽 <span class="muted">／ 60 分鐘</span></strong><span>點候選定位 · 框線為局部視窗</span></div><div class="track overview-track">${seekInput(0,3600,'全片導覽位置')}${candidateBlocks(0,3600)}<span class="overview-window" style="${rangeStyle(state.from,state.to,0,3600)}"></span>${playhead(0,3600)}</div>${ruler(0,3600)}</section>`; }
function cards(){ return `<div class="candidate-cards">${candidates.map(c=>`<button type="button" class="candidate-card ${c.kind}" data-candidate="${c.id}" aria-pressed="${state.selected===c.id}" aria-label="候選 ${c.id}：${c.tag}，${c.title}"><span class="card-thumb" aria-hidden="true"><span>${shortTime(c.end-c.start)}</span></span><span class="card-top"><span class="card-index">#0${c.id}</span><span class="kind-tag ${c.kind}">${c.tag}</span></span><strong>${c.title}</strong><small><span class="mono">${shortTime(c.start)}—${shortTime(c.end)}</span><br>${c.detail}</small></button>`).join('')}</div>`; }
function footer({step=false}={}){ let actions=button('preview-clip','預覽片段','play'); if(step&&state.step<3){actions+=button('next-step',state.step===1?'繼續精剪':'前往核對','next','primary');}else{actions+=button('export','模擬匯出','export','primary',`data-export ${state.reviewed?'':'disabled'}`);}return `<footer class="review-footer"><div><strong><span data-duration>${shortTime(state.victory+state.postroll-state.start)}</span> 片長 · 收尾 <span data-tail-value>${state.postroll}</span> 秒</strong>${!step||state.step===3?`<label class="review-label"><input type="checkbox" data-reviewed ${state.reviewed?'checked':''}>我已核對：完整成功挑戰，含勝利與收尾</label><span data-export-hint>${state.reviewed?'已核對，可試用模擬匯出':'勾選核對後可試用模擬匯出'}</span>`:'<span>草稿會保留，可隨時回到前一步。</span>'}</div><div class="footer-actions">${actions}</div></footer>`; }
function stepLayout(){return `<nav class="step-nav" aria-label="剪輯步驟">${['找候選','精剪範圍','核對片段'].map((label,i)=>`<button type="button" data-step="${i+1}" ${state.step===i+1?'aria-current="step"':''}><span>${i+1}</span>${label}</button>`).join('')}</nav><div class="step-content">${previewRow()}${state.step===1?`<section class="timeline-panel" aria-label="選擇候選"><div class="timeline-heading"><h3>先找到值得保留的那一場</h3><span class="scale-label">3 段 AI 候選</span></div>${cards()}</section>${overview()}`:state.step===2?timelinePanel():`<section class="step-review" aria-label="片段核對清單"><article class="checkpoint"><span>01 / 開始</span><strong data-review-start>${time(state.start)}</strong><p>從成功挑戰開始，沒有前一次死亡或跑圖。</p>${button('preview-start','播放開頭 8 秒','play')}</article><article class="checkpoint"><span>02 / 勝利</span><strong data-review-victory>${time(state.victory)}</strong><p>確認勝利訊號確實出現在這場戰鬥中。</p>${button('preview-victory','播放勝利附近','trophy')}</article><article class="checkpoint"><span>03 / 收尾</span><strong>保留 <span data-tail-value>${state.postroll}</span> 秒</strong><p>勝利之後留出呼吸，完整收住情緒。</p>${button('preview-tail','播放收尾','play')}</article></section>`}</div>${footer({step:true})}`; }
function variant(){if(active==='A')return `${previewRow()}${timelinePanel({all:true,title:'剪輯與原片對照'})}${footer()}`;if(active==='B')return `${previewRow()}${overview()}${timelinePanel({title:'局部精剪',context:true})}${footer()}`;if(active==='C')return stepLayout();if(active==='D')return `<div class="card-workspace"><aside class="candidate-rail" aria-label="候選片段"><div class="candidate-rail-heading"><span>候選片段</span><span class="muted">03</span></div><p>選一場核對；失敗片段僅供查看。</p>${cards()}<p class="context-note">勝利草稿與查看候選分開保留。</p></aside><div class="rail-main">${player()}${timelinePanel()}${footer()}</div></div>`;return `${previewRow()}<div class="drawer-heading"><div>${icon('scissors')}<strong>剪輯工作台</strong><span data-drawer-summary>${shortTime(state.start)}—${shortTime(state.victory+state.postroll)} · ${shortTime(state.victory+state.postroll-state.start)}</span></div><label class="drawer-size">高度 <input type="range" data-drawer-height min="250" max="390" step="10" value="${state.drawerHeight}" aria-label="剪輯抽屜高度"></label>${button('drawer',state.drawer?'收合工作台':'展開工作台',state.drawer?'down':'up','',`aria-expanded="${state.drawer}" aria-controls="edit-drawer"`)}</div><div class="drawer ${state.drawer?'':'closed'}" id="edit-drawer" style="--drawer-height:${state.drawerHeight}px">${timelinePanel({all:true,title:'對照與精剪'})}<p class="drawer-summary">${icon('check')} 收合與展開保留播放位置、縮放和剪輯範圍。</p></div>${footer()}`;}
function renderNav(){document.querySelector('.concept-nav').innerHTML=Object.entries(concepts).map(([key,c])=>`<button type="button" class="concept-option" data-concept="${key}" ${key===active?'aria-current="page"':''}><span class="concept-letter">${key}</span><span><strong>${c.name}</strong><small>${c.short}</small></span></button>`).join('');const c=concepts[active];document.querySelector('#concept-description').innerHTML=`<div><h2>${c.title}</h2><p>${c.description}</p></div><div class="tradeoff"><span>${c.benefit}</span><p>${c.cost}</p></div>`;}
function render({restoreFocus=true}={}){const focused=document.activeElement;const key=focused?.dataset;const focusKey=restoreFocus&&workspace.contains(focused)?key?.action?`[data-action="${key.action}"]`:key?.candidate?`[data-candidate="${key.candidate}"]`:key?.step?`[data-step="${key.step}"]`:null:null;workspace.className=`workspace scheme-${active.toLowerCase()}`;workspace.dataset.activeStep=String(state.step);workspace.innerHTML=`${library()}<div class="studio-main"><header class="studio-header"><div class="project-title">${icon('film')}艾爾登法環 · 女武神挑戰</div><span>方案 ${active} · ${concepts[active].name}</span></header><div class="editor-body">${variant()}</div><div class="export-message" role="status" data-export-message ${state.exported?'':'hidden'}>模擬匯出完成：${time(state.start)}—${time(state.victory+state.postroll)}。此原型未產生影片檔案。</div></div>`;sync();if(focusKey)workspace.querySelector(focusKey)?.focus({preventScroll:true});}
function sync(){const end=state.victory+state.postroll;workspace.querySelectorAll('[data-current]').forEach(el=>el.textContent=time(state.current));workspace.querySelectorAll('[data-duration]').forEach(el=>el.textContent=shortTime(end-state.start));workspace.querySelectorAll('[data-end]').forEach(el=>el.textContent=time(end));workspace.querySelectorAll('[data-tail-value]').forEach(el=>el.textContent=state.postroll);workspace.querySelectorAll('[data-time]').forEach(el=>{if(document.activeElement!==el&&!el.hasAttribute('aria-invalid'))el.value=time(state[el.dataset.time]);});workspace.querySelectorAll('[data-playhead]').forEach(el=>{const from=+el.dataset.from,to=+el.dataset.to;el.style.left=`${position(state.current,from,to)}%`;el.style.display=within(state.current,from,to)?'block':'none';});workspace.querySelectorAll('[data-selection],[data-tail]').forEach(el=>{const from=+el.dataset.from,to=+el.dataset.to;const start=el.hasAttribute('data-tail')?state.victory:state.start;el.style.left=`${position(start,from,to)}%`;el.style.width=`${Math.max(0,position(end,from,to)-position(start,from,to))}%`;el.style.display=end>from&&start<to?'block':'none';});workspace.querySelectorAll('[data-edge]').forEach(el=>{const edge=el.dataset.edge,at=state[edge],from=+el.dataset.from,to=+el.dataset.to;el.style.left=`${position(at,from,to)}%`;el.style.display=within(at,from,to)?'block':'none';el.setAttribute('aria-valuenow',at);el.setAttribute('aria-valuetext',time(at));el.setAttribute('aria-valuemin',edge==='start'?'0':state.start+1);el.setAttribute('aria-valuemax',edge==='start'?state.victory-1:3600-state.postroll);});workspace.querySelectorAll('[data-seek]').forEach(el=>{el.value=clamp(state.current,+el.min,+el.max);el.setAttribute('aria-valuetext',time(clamp(state.current,+el.min,+el.max)));});workspace.querySelectorAll('[data-play-button]').forEach(el=>{el.innerHTML=icon(state.playing?'pause':'play');el.setAttribute('aria-label',state.playing?'暫停示意預覽':'播放示意預覽');});const review=workspace.querySelector('[data-reviewed]');if(review){review.checked=state.reviewed;review.disabled=!!state.error;}const exp=workspace.querySelector('[data-export]');if(exp)exp.disabled=!state.reviewed||!!state.error;const hint=workspace.querySelector('[data-export-hint]');if(hint)hint.textContent=state.reviewed?'已核對，可試用模擬匯出':'勾選核對後可試用模擬匯出';const message=workspace.querySelector('[data-export-message]');if(message)message.hidden=!state.exported;const event=workspace.querySelector('[data-scene-event]');if(event){event.innerHTML=state.current>=2702&&state.current<2720?'DEMIGOD FELLED<small>勝利訊號 · 示意</small>':state.current>=1228&&state.current<1245?'YOU DIED<small>失敗候選 · 不採用於剪輯</small>':'';}const health=workspace.querySelector('[data-health]');if(health)health.style.width=state.current>=2702?'0%':`${clamp((2702-state.current)/166*100,2,72)}%`;const summary=workspace.querySelector('[data-drawer-summary]');if(summary)summary.textContent=`${shortTime(state.start)}—${shortTime(end)} · ${shortTime(end-state.start)}`;const error=workspace.querySelector('#edit-error');if(error){error.hidden=!state.error;error.textContent=state.error;}}
function dirty(){state.reviewed=false;state.exported=false;state.error='';workspace.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));}
function setEdge(edge,at){dirty();state[edge]=Math.round(edge==='start'?clamp(at,0,state.victory-1):clamp(at,state.start+1,3600-state.postroll));state.current=state[edge];state.playing=false;sync();}
function chooseCandidate(id){const c=candidates.find(x=>x.id===id);state.selected=id;state.current=c.start;state.playing=false;localize(c.start,c.end);announce(`正在查看候選 ${id}，${c.tag}。目前勝利草稿保持不變。`);render();}
function setConcept(key){if(!concepts[key])return;state.playing=false;active=key;state=states[key];state.playing=false;playUntil=null;drag=null;renderNav();render({restoreFocus:false});document.title=`BossCut · ${key} ${concepts[key].name}`;document.querySelector(`.concept-nav [data-concept="${key}"]`)?.focus({preventScroll:true});}
function preview(start,end){state.current=start;state.playing=true;playUntil=end;sync();}
const actions={
  'play':()=>{state.playing=!state.playing;playUntil=null;sync();},
  'frame-back':()=>{state.current=clamp(state.current-1,0,3600);state.playing=false;sync();},
  'frame-next':()=>{state.current=clamp(state.current+1,0,3600);state.playing=false;sync();},
  'fit':()=>{localize();render();},
  'full':()=>{state.from=0;state.to=3600;render();},
  'zoom-in':()=>{const span=Math.max(25,(state.to-state.from)/2);state.from=clamp(state.current-span/2,0,3600-span);state.to=state.from+span;render();},
  'evidence':()=>{state.showEvidence=!state.showEvidence;render();},
  'start-minus':()=>setEdge('start',state.start-1),
  'start-plus':()=>setEdge('start',state.start+1),
  'jump-victory':()=>{state.current=state.victory;state.playing=false;if(!within(state.current,state.from,state.to))localize();render();},
  'evidence-victory':()=>{state.current=2702;state.playing=false;sync();},
  'preview-clip':()=>{localize();render();preview(state.start,state.victory+state.postroll);},
  'preview-start':()=>preview(state.start,Math.min(state.start+8,state.victory+state.postroll)),
  'preview-victory':()=>preview(Math.max(state.start,state.victory-4),Math.min(state.victory+3,state.victory+state.postroll)),
  'preview-tail':()=>preview(state.victory,state.victory+state.postroll),
  'next-step':()=>{state.step=Math.min(3,state.step+1);if(state.step===2)localize();state.playing=false;render();const step=workspace.querySelector(`[data-step="${state.step}"]`);step?.focus({preventScroll:true});},
  'drawer':()=>{state.drawer=!state.drawer;render();},
  'export':()=>{if(!state.reviewed)return;state.exported=true;state.playing=false;sync();const message=workspace.querySelector('[data-export-message]');message.textContent=`模擬匯出完成：${time(state.start)}—${time(state.victory+state.postroll)}。此原型未產生影片檔案。`;announce(message.textContent);}
};
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.concept){const key=target.dataset.concept;if(target.closest('table'))document.querySelector('.concept-nav').scrollIntoView({block:'start'});if(location.hash===`#${key}`)setConcept(key);else location.hash=key;return;}if(target.dataset.candidate){chooseCandidate(+target.dataset.candidate);return;}if(target.dataset.step){state.step=+target.dataset.step;state.playing=false;if(state.step===2)localize();render();return;}actions[target.dataset.action]?.();});
workspace.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-seek]')){state.current=+el.value;state.playing=false;sync();}if(el.matches('[data-drawer-height]')){state.drawerHeight=+el.value;workspace.querySelector('.drawer').style.setProperty('--drawer-height',`${state.drawerHeight}px`);}});
workspace.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-seek]')&&el.max==='3600'&&(active==='B'||(active==='C'&&state.step===1))){const span=Math.min(state.to-state.from,360);state.from=clamp(state.current-span/2,0,3600-span);state.to=state.from+span;render();workspace.querySelector('.overview-panel [data-seek]')?.focus({preventScroll:true});}if(el.matches('[data-speed]'))state.speed=+el.value;if(el.matches('[data-postroll]')){dirty();state.postroll=+el.value;state.victory=Math.min(state.victory,3600-state.postroll);sync();}if(el.matches('[data-reviewed]')){state.reviewed=el.checked;state.exported=false;sync();}if(el.matches('[data-time]')){const match=el.value.match(/^(\d{2}):([0-5]\d):([0-5]\d)$/);const at=match?+match[1]*3600 + +match[2]*60 + +match[3]:NaN;const edge=el.dataset.time;const valid=Number.isFinite(at)&&at>=0&&(edge==='start'?at<state.victory:at>state.start&&at+state.postroll<=3600);if(!valid){state.reviewed=false;state.exported=false;state.error='請輸入 HH:MM:SS；開始須早於勝利，收尾須在原片內。';el.setAttribute('aria-invalid','true');sync();return;}el.removeAttribute('aria-invalid');setEdge(edge,at);el.value=time(state[edge]);}});
workspace.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-edge]');if(!el||event.button!==0)return;event.preventDefault();el.focus({preventScroll:true});const rect=el.closest('[data-track]').getBoundingClientRect();drag={element:el,edge:el.dataset.edge,from:+el.dataset.from,to:+el.dataset.to,left:rect.left,width:rect.width,pointer:event.pointerId};el.setPointerCapture(event.pointerId);state.playing=false;});
workspace.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.pointer)return;setEdge(drag.edge,drag.from+clamp((event.clientX-drag.left)/drag.width,0,1)*(drag.to-drag.from));});
function endDrag(event){if(!drag||event.pointerId!==drag.pointer)return;const d=drag;drag=null;if(d.element.hasPointerCapture(event.pointerId))d.element.releasePointerCapture(event.pointerId);announce(`${d.edge==='start'?'開始':'勝利'}時間 ${time(state[d.edge])}`);}
workspace.addEventListener('pointerup',endDrag);workspace.addEventListener('pointercancel',endDrag);workspace.addEventListener('lostpointercapture',()=>{drag=null;});
workspace.addEventListener('keydown',event=>{const el=event.target.closest('[data-edge]');if(el&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const edge=el.dataset.edge;const value=event.key==='Home'?+el.getAttribute('aria-valuemin'):event.key==='End'?+el.getAttribute('aria-valuemax'):state[edge]+(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?5:1);setEdge(edge,value);}});
document.querySelector('#focus-toggle').addEventListener('click',event=>{const focus=document.body.classList.toggle('focus-mode');event.currentTarget.textContent=focus?'顯示方案說明':'專注看版面';event.currentTarget.setAttribute('aria-pressed',String(focus));window.scrollTo(0,0);});
document.querySelector('a[href="#comparison"]').addEventListener('click',()=>{document.body.classList.remove('focus-mode');document.querySelector('#focus-toggle').textContent='專注看版面';document.querySelector('#focus-toggle').setAttribute('aria-pressed','false');});
document.querySelector('#reset-demo').addEventListener('click',()=>{states[active]=defaults();state=states[active];playUntil=null;render({restoreFocus:false});announce(`方案 ${active} 已重設。`);});
window.addEventListener('hashchange',()=>{if(concepts[location.hash.slice(1)])setConcept(location.hash.slice(1));});
document.addEventListener('visibilitychange',()=>{if(document.hidden){state.playing=false;sync();}});
setInterval(()=>{if(!state.playing)return;state.current=Math.min(3600,state.current+.1*state.speed);if(state.current>=(playUntil??3600)){state.current=playUntil??3600;state.playing=false;playUntil=null;}sync();},100);
document.querySelector('#comparison-rows').innerHTML=Object.entries(concepts).map(([key,c])=>`<tr><td><button type="button" data-concept="${key}">${key} · ${c.name}</button></td><td>${c.axis}</td><td>${c.audience}</td><td>${c.cost}</td><td>${c.recommendation}</td></tr>`).join('');
document.querySelector('.lab-brand .brand-symbol').innerHTML=icon('scissors');
renderNav();render({restoreFocus:false});
